import{_ as o,o as t,c as a,a2 as s}from"./chunks/framework.vLhlLNVn.js";const b=JSON.parse('{"title":"How do I enable and open the ESPHome dashboard?","description":"","frontmatter":{"order":4,"adapter":"esphome","editLink":"https://github.com/DrozmotiX/ioBroker.esphome/edit/main/docs/en/01.erste-schritte/04.dashboard-einschalten.md"},"headers":[],"relativePath":"adapter/esphome/erste-schritte/dashboard-einschalten.md","filePath":"adapter/esphome/erste-schritte/dashboard-einschalten.md","lastUpdated":null}'),r={name:"adapter/esphome/erste-schritte/dashboard-einschalten.md"};function h(d,e,n,i,l,c){return t(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="how-do-i-enable-and-open-the-esphome-dashboard" tabindex="-1">How do I enable and open the ESPHome dashboard? <a class="header-anchor" href="#how-do-i-enable-and-open-the-esphome-dashboard" aria-label="Permalink to &quot;How do I enable and open the ESPHome dashboard?&quot;">​</a></h1><p><a id="dashboard-tab-not-open-localhost"></a></p><h2 id="why-does-the-dashboard-tab-not-open-localhost-refused-to-connect" tabindex="-1">Why does the dashboard tab not open (&quot;localhost refused to connect&quot;)? <a class="header-anchor" href="#why-does-the-dashboard-tab-not-open-localhost-refused-to-connect" aria-label="Permalink to &quot;Why does the dashboard tab not open (&quot;localhost refused to connect&quot;)?&quot;">​</a></h2><p>Enter the address of your ioBroker host under &quot;IP-Address where ESPHome Dashboard is running to integrate in ioBroker Admin&quot;, without a port. Do not use <code>localhost</code> or <code>127.0.0.1</code>.</p><p>The tab shows the page under &quot;URL of ESPHome Dashboard&quot;. Your browser loads this page, not the ioBroker host. <code>localhost</code> therefore points to the computer in front of you, and the browser reports &quot;localhost refused to connect&quot;.</p><h3 id="how-to-do-it" tabindex="-1">How to do it <a class="header-anchor" href="#how-to-do-it" aria-label="Permalink to &quot;How to do it&quot;">​</a></h3><ol><li>Open the instance settings, tab &quot;ESPHome Dashboard&quot;.</li><li>Tick &quot;Enable ESPHome Dashboard&quot;.</li><li>Pick an address of the ioBroker host from the list in the IP field. The list offers IPv4 and IPv6 addresses, a host name works too. Do not add a port, the adapter adds it itself.</li><li>Under &quot;Advanced&quot; you find &quot;Port of ESPHome Dashboard&quot;, default <code>6052</code>. Below it, &quot;URL of ESPHome Dashboard&quot; fills in by itself, e.g. <code>http://192.168.x.y:6052</code>. Enter your own URL last, because changing the IP or port overwrites it.</li><li>Save. The instance restarts.</li><li>Open the ESPHome tab in the admin menu. While the dashboard starts, it shows a hint and the start log. As soon as the dashboard answers, it appears by itself. On the first start this takes a few minutes.</li></ol><p>If the tab shows a text instead of the dashboard, the text names the reason: instance not running, dashboard not enabled, no URL entered, or start failed. For the last case see <a href="./../fehlerbehebung/dashboard-startet-nicht#dashboard-not-start-pillow-esphome">Why does the dashboard not start?</a>.</p><p><strong>See also:</strong> <a href="./../anleitungen/dashboard-nutzen#show-dashboard-admin-tab-using">How do I show the dashboard in the admin tab when using HTTPS?</a></p><p><a id="flash-device-first-time-if"></a></p><h2 id="how-do-i-flash-a-device-for-the-first-time-if-the-server-has-no-usb-access" tabindex="-1">How do I flash a device for the first time if the server has no USB access? <a class="header-anchor" href="#how-do-i-flash-a-device-for-the-first-time-if-the-server-has-no-usb-access" aria-label="Permalink to &quot;How do I flash a device for the first time if the server has no USB access?&quot;">​</a></h2><p>The first flash needs a cable connection to the device. If the ioBroker host has no USB access, e.g. in a VM or a container, flash from your own PC. Afterwards you install changes over Wi-Fi (OTA) from the dashboard of the adapter.</p><ol><li>Create the device in the dashboard and choose &quot;Manual download&quot; under &quot;Install&quot;.</li><li>Download the firmware.</li><li>Connect the device to your PC by USB and flash the file with a flash tool, e.g. <a href="https://web.esphome.io" target="_blank" rel="noreferrer">ESPHome Web</a>.</li><li>As soon as the device is on Wi-Fi, choose &quot;Wirelessly&quot; under &quot;Install&quot;.</li></ol><p>&quot;Plug into this computer&quot; in the dashboard only works when you open the dashboard over HTTPS.</p><p><strong>See also:</strong> <a href="./../anleitungen/dashboard-nutzen#show-dashboard-admin-tab-using">Show the dashboard with HTTPS</a></p>',15)])])}const f=o(r,[["render",h]]);export{b as __pageData,f as default};
